#!/usr/bin/env python3
"""Author a research coverage map; partial evidence is never complete clinical coverage."""
import json
from pathlib import Path
D=Path(__file__).resolve().parents[1]
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
extracts=[x for p in (D/'research').glob('breadth-*.json') for x in json.loads(p.read_text())]
byid={x['id']:x for x in extracts}
families=[('wrist-trauma','Suspected wrist fracture',['acr-acute-wrist-trauma-imaging-pathway']),('chest-pain','Adult acute chest pain',['acc-2022-ed-acute-chest-pain-initial-pathway']),('stroke','Suspected acute stroke',['aha-asa-2026-suspected-ischemic-stroke-emergency-pathway']),('pediatric-asthma','Pediatric respiratory exacerbation',['gina-2026-pediatric-acute-asthma-emergency-assessment']),('obstetric-triage','Urgent pregnancy-related presentation',['acog-2016-hospital-based-obstetric-triage']),('behavioral-crisis','Behavioral-health crisis',['samhsa-2025-behavioral-health-crisis-continuum']),('sepsis','Infection and suspected sepsis',[]),('abdominal-pain','Abdominal pain and emergency surgery',[]),('polytrauma','Major trauma and resuscitation',[]),('toxicology','Poisoning and overdose',[]),('metabolic','Diabetes and metabolic emergencies',[]),('geriatric','Falls, delirium and frailty',[]),('neonatal','Newborn and neonatal intensive care',[]),('oncology','Cancer therapy and complications',[]),('dialysis','Renal replacement encounters',['cms-esrd-interdisciplinary-dialysis-plan']),('elective-surgery','Scheduled surgery and perioperative care',[]),('icu','Critical care and ICU transfers',[]),('general-inpatient','Ward admission, daily care and discharge',[]),('rehabilitation','Rehabilitation and functional recovery',[]),('palliative','Palliative and end-of-life care',[]),('ambulatory','Outpatient consultation and follow-up',[]),('discharge-placement','Post-acute placement and home services',['ahrq-red-case-management-discharge'])]
common_gaps=['Complete clinician-reviewed branch conditions and exclusions','Task-level local role responsibility and escalation ownership','Resource availability, service-time distributions and dependencies','EHR actions and permissions for each role','Patient goals, communication/access needs and follow-up','Versioned plan/service applicability where insurance matters']
rows=[]
for key,title,refs in families:
 assert all(r in byid for r in refs)
 rows.append({'id':key,'title':title,'source_record_ids':refs,'coverage_status':'partial_guidance' if refs else 'dedicated_pathway_not_acquired_this_pass','local_validation':'not_established','missing':common_gaps,'note':'General timing or support-role evidence elsewhere does not make this encounter complete. Dialysis evidence is longitudinal ESRD guidance, not an acute inpatient protocol.' if key=='dialysis' else 'Coverage applies to this map only; related general evidence may exist elsewhere.'})
roles=['patient','caregiver or surrogate','EMS','triage nurse','bedside nurse','charge nurse','nursing assistant','ED physician','resident or fellow','advanced practice clinician','hospitalist','specialist consultant','surgeon','anesthesiology clinician','midwife or obstetric clinician','pediatric clinician','psychiatry clinician','pharmacist','pharmacy technician','respiratory therapist','laboratory technologist','phlebotomist','radiology technologist','radiologist','blood bank staff','dialysis nurse','physical therapist','occupational therapist','speech-language pathologist','dietitian','case manager','social worker','qualified interpreter','transport staff','bed manager','environmental services','sterile processing staff','infection preventionist','registration staff','financial counselor','utilization reviewer','coding and billing staff','IT or clinical informatics','biomedical engineering','security','chaplain or spiritual care']
write(D/'knowledge/encounter-coverage.json',{'version':1,'status':'authored_research_map_not_clinical_protocol','scope':'Non-exhaustive hospital encounter families; no claim every patient or specialty is covered','families':rows,'role_inventory':roles,'role_inventory_basis':'Analyst-authored planning taxonomy; not a measured staffing list or canonical role-permission mapping','role_evidence_record_ids':[x['id'] for x in json.loads((D/'research/breadth-roles.json').read_text())],'cross_cutting_dimensions':['age and developmental stage','acuity and arrival route','chief complaint and diagnostic uncertainty','comorbidities and medication history','language/accessibility','capacity, consent and surrogate','pregnancy status where relevant','infection/isolation requirements','insurance product and effective date','social support, transport and placement','staffing, space, equipment and workload','time of day and handoff boundaries']})
contract={'version':1,'status':'proposed_contract_not_implemented_simulator','required_per_transition':['event_id','from_state','to_state','trigger_or_decision','actor_role','required_information','resources_acquired_and_released','ehr_action_and_permission','duration_model_or_explicit_unknown','source_record_ids','evidence_kind','inference_and_transfer_limits','exception_or_escalation','review_status'],'separate_state_tracks':['clinical condition and findings','orders/results and care tasks','physical location and resource occupancy','communication/consent/handoffs','administrative eligibility/authorization/claims'],'invariants':['Emergency screening/stabilization must not wait for an invented payer authorization gate.','A suspected condition does not become confirmed without authored evidence.','Real clinician identities do not imply known personality, behavior, availability or permissions.','A guideline timing goal is not an observed service-time distribution.','Training assessment improvements do not establish actual patient-outcome improvement.','Unacquired policy or timing stays unknown or explicitly assumed; never silently observed.'],'fracture_example':{'source_record_ids':['acr-acute-wrist-trauma-imaging-pathway','admin-emtala-screening','admin-aetna-emergency-authorization','admin-aetna-plan-specific-priorauth'],'authored_skeleton':['arrival and urgency assessment','medical assessment','initial radiographs when appropriate','result review and persistent-suspicion branch','injury-specific treatment decision (missing complete protocol)','disposition, handoff and follow-up (missing complete protocol)'],'missing_before_complete':['Neurovascular/open-injury escalation and full injury-specific care source pack','Reviewed treatment and disposition branches','Local orthopedic access and staffing','Specific Aetna plan/service/network/benefit snapshot','Calibrated or explicitly adopted duration models'],'status':'partial_example_not_runnable_or_clinically_approved'}}
write(D/'specs/encounter-evidence-contract.json',contract)
print(len(rows),'encounter families;',len(roles),'planning roles')
